const e = $input.first().json;
const exec = e.execution || {};
const trig = e.trigger || {};
const err = exec.error || trig.error || {};
const msg = String(err.message || 'Unknown error');
const text = (msg + ' ' + (err.description || '') + ' ' + (err.stack || '')).toLowerCase();
const node = exec.lastNodeExecuted || (err.node && err.node.name) || 'Unknown node';
const workflow = (e.workflow && e.workflow.name) || 'Unknown workflow';

const rules = [
  [/unexpected token|json|parse|schema|output parser/, 'parsing', 'medium'],
  [/401|403|unauthori[sz]ed|forbidden|invalid_grant|access token|refresh token|credential|authori[sz]/, 'auth', 'critical'],
  [/429|402|rate limit|quota|too many requests|insufficient credits|billing/, 'quota-or-credits', 'critical'],
  [/timeout|timed out|etimedout|econnreset|econnrefused|enotfound|socket|502|503|504/, 'network', 'high'],
  [/pdf|ocr|extract|binary|mime|no data/, 'file-processing', 'medium'],
  [/not found|404|does not exist|spreadsheet|range|sheet/, 'resource-missing', 'high'],
];
let type = 'other', severity = 'medium';
for (const [re, t, sev] of rules) { if (re.test(text)) { type = t; severity = sev; break; } }
if (!exec.id) { type = 'trigger-failure'; severity = 'critical'; }

return [{ json: { time: new Date().toISOString(), workflow, node, type, severity,
  message: msg.slice(0, 250), executionId: exec.id || '', executionUrl: exec.url || '' } }];

// Same workflow + node: only one email per window. Sheet columns: Time | Workflow | Node | Error | Status
const WINDOW_MIN = 60;
const cur = $('Classify Error').first().json;
const rows = $input.all().map(i => i.json).filter(r => r['Workflow']);
const now = Date.now();
const recent = rows.some(r =>
  r['Workflow'] === cur.workflow && r['Node'] === cur.node &&
  String(r['Status']).toLowerCase() === 'alerted' &&
  (now - new Date(r['Time']).getTime()) < WINDOW_MIN * 60000);
const errorText = `[${cur.type}/${cur.severity}] ${cur.message}` + (cur.executionId ? ` (exec ${cur.executionId})` : '');
return [{ json: { 'Time': cur.time, 'Workflow': cur.workflow, 'Node': cur.node,
  'Error': errorText.slice(0, 300), 'Status': recent ? 'throttled' : 'alerted' } }];

const HOURS = 24;
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows = $input.all().map(i => i.json).filter(r => r['Time']);
const since = Date.now() - HOURS * 3600 * 1000;
const recent = rows.filter(r => new Date(r['Time']).getTime() >= since);
if (!recent.length) return [{ json: { hasData: false } }];

const groups = {};
for (const r of recent) {
  const k = r['Workflow'] + '|' + r['Node'];
  (groups[k] = groups[k] || { w: r['Workflow'], n: r['Node'], c: 0, last: r['Error'] }).c++;
  groups[k].last = r['Error'];
}
const list = Object.values(groups).sort((a, b) => b.c - a.c);
const critical = recent.filter(r => String(r['Error']).includes('/critical]')).length;

const html = `<h3>Recruitment automation: last ${HOURS}h</h3>
<p><b>${recent.length}</b> events (${critical} critical) across ${list.length} distinct issues.</p>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-family:Arial;font-size:13px">
<tr style="background:#eee"><th>Count</th><th>Workflow</th><th>Node</th><th>Latest error</th></tr>
${list.map(g => `<tr><td>${g.c}</td><td>${esc(g.w)}</td><td>${esc(g.n)}</td><td>${esc(g.last)}</td></tr>`).join('')}
</table>`;
return [{ json: { hasData: true, subject: `Daily digest: ${recent.length} automation event(s), ${critical} critical`, html } }];

// ---- CONFIG: matches the Applications tab headers ----
const CONFIG = {
  TIME_COLUMN: 'Applied At',
  STATUS_COLUMN: 'Status',
  SCORE_COLUMN: 'Score',
  NAME_COLUMN: 'Name',
  PENDING_STATUSES: ['', 'new', 'pending', 'waiting', 'received', 'submitted', 'applied'],
  STUCK_AFTER_HOURS: 3   // Recruitment 2 runs hourly
};
// ------------------------------------------------------
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
if (!rows.length) return [{ json: { hasStuck: false, stuckCount: 0, oldestHours: 0 } }];

const missing = [CONFIG.STATUS_COLUMN, CONFIG.TIME_COLUMN, CONFIG.SCORE_COLUMN].filter(c => !(c in rows[0]));
if (missing.length) {
  return [{ json: { hasStuck: true, stuckCount: 0, oldestHours: 0,
    subject: 'Heartbeat config mismatch: column not found',
    html: `<p>Column(s) <b>${esc(missing.join(', '))}</b> not found in the Applications tab.</p><p>Columns found: ${esc(Object.keys(rows[0]).join(', '))}</p>` } }];
}

const now = Date.now();
const stuck = []; let unparsed = 0;
for (const r of rows) {
  const status = String(r[CONFIG.STATUS_COLUMN] ?? '').trim().toLowerCase();
  const scored = String(r[CONFIG.SCORE_COLUMN] ?? '').trim() !== '';
  if (scored || !CONFIG.PENDING_STATUSES.includes(status)) continue;   // already processed by Recruitment 2
  const t = new Date(r[CONFIG.TIME_COLUMN]).getTime();
  if (isNaN(t)) { unparsed++; continue; }
  const ageH = (now - t) / 3600000;
  if (ageH >= CONFIG.STUCK_AFTER_HOURS) stuck.push({ name: r[CONFIG.NAME_COLUMN] || '(no name)', ageH: Math.round(ageH * 10) / 10 });
}
stuck.sort((a, b) => b.ageH - a.ageH);
const html = `<h3>Applications stuck in the pipeline</h3>
<p>${stuck.length} application(s) waiting more than ${CONFIG.STUCK_AFTER_HOURS}h without being scored by Recruitment 2.</p>
<ul>${stuck.slice(0, 20).map(s => `<li>${esc(s.name)}: ${s.ageH}h</li>`).join('')}</ul>
${unparsed ? `<p>Note: ${unparsed} pending row(s) have an unreadable "${esc(CONFIG.TIME_COLUMN)}" date.</p>` : ''}
<p>Check that "Recruitment 2" is published and its Every Hour trigger is running.</p>`;
return [{ json: {
  hasStuck: stuck.length > 0 || unparsed > 0,
  stuckCount: stuck.length,
  oldestHours: stuck.length ? stuck[0].ageH : 0,
  subject: stuck.length ? `${stuck.length} application(s) stuck for ${CONFIG.STUCK_AFTER_HOURS}h+` : `${unparsed} pending application(s) with unreadable dates`,
  html
} }];
